{
  "name": "DLPC900 数字微镜器件",
  "name_en": "DLPC900-based Digital Micromirror Device",
  "manufacturer": "Texas Instruments",
  "description": "基于 Texas Instruments DLPC900 控制器的数字微镜器件（DMD）图案投影系统，常见型号包括 DLP6500 和 DLP9000。该设备通过微镜阵列高速切换空间光图案，可用于实验室中的结构光照明、光学图案投射、触发同步显示以及其他需要精确时序控制的光调制实验。",
  "description_en": "A digital micromirror device (DMD) pattern projection system based on the Texas Instruments DLPC900 controller, including models such as the DLP6500 and DLP9000. It uses a micromirror array to switch spatial light patterns at high speed, making it suitable for laboratory applications such as structured illumination, optical pattern projection, trigger-synchronized display, and other light modulation experiments requiring precise timing control.",
  "tag_hints": [
    "DMD spatial light modulator",
    "pattern projection",
    "structured illumination",
    "trigger synchronization",
    "high-speed optical modulation",
    "DLPC900",
    "DLP6500",
    "DLP9000"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化 DMD 设备通信。",
      "description_en": "Initialize communication with the DMD."
    },
    {
      "action_name": "auto-send_raw_command",
      "description": "向 DMD 发送原始命令数据包。",
      "description_en": "Send a raw command packet to the DMD."
    },
    {
      "action_name": "auto-send_command",
      "description": "向 DMD 发送带协议头的命令。",
      "description_en": "Send a formatted command with protocol header to the DMD."
    },
    {
      "action_name": "auto-decode_response",
      "description": "解析 DMD 返回的响应数据。",
      "description_en": "Decode a response returned by the DMD."
    },
    {
      "action_name": "auto-read_error_code",
      "description": "读取上一条命令的错误代码。",
      "description_en": "Read the error code from the last command."
    },
    {
      "action_name": "auto-read_error_description",
      "description": "读取上一条错误的文字描述。",
      "description_en": "Read the text description of the last error."
    },
    {
      "action_name": "auto-set_trigger_out",
      "description": "配置 DMD 输出触发信号的延时与极性。",
      "description_en": "Configure the delay and polarity of the DMD trigger output."
    },
    {
      "action_name": "auto-set_trigger_in1",
      "description": "set trigger input 1 delay and advance edge",
      "description_en": "set trigger input 1 delay and advance edge"
    },
    {
      "action_name": "auto-set_trigger_in2",
      "description": "set trigger input 2 start edge polarity",
      "description_en": "set trigger input 2 start edge polarity"
    },
    {
      "action_name": "auto-set_pattern_mode",
      "description": "设置 DMD 的图案显示模式。",
      "description_en": "Set the DMD pattern display mode."
    },
    {
      "action_name": "auto-start_stop_sequence",
      "description": "启动、停止或暂停图案序列播放。",
      "description_en": "Start, stop, or pause a pattern sequence."
    },
    {
      "action_name": "auto-execute_fwbatch",
      "description": "执行设备固件中存储的批处理文件。",
      "description_en": "Execute a batch file stored in device firmware."
    },
    {
      "action_name": "auto-set_fwbatch_delay",
      "description": "设置固件批处理命令之间的延时。",
      "description_en": "Set the delay between firmware batch commands."
    },
    {
      "action_name": "auto-upload_pattern_sequence",
      "description": "向 DMD 上传按序播放的图案序列。",
      "description_en": "Upload a pattern sequence to the DMD for playback."
    },
    {
      "action_name": "auto-set_pattern_sequence",
      "description": "配置 DMD 使用已存储图案的播放序列。",
      "description_en": "Configure a DMD pattern sequence using stored patterns."
    },
    {
      "action_name": "auto-program_dmd_seq",
      "description": "生成并写入一组 DMD 图案序列配置。",
      "description_en": "Generate and program a DMD pattern sequence configuration."
    },
    {
      "action_name": "auto-decode_command",
      "description": "解析 DMD 命令数据包内容。",
      "description_en": "Decode the contents of a DMD command packet."
    },
    {
      "action_name": "auto-decode_flag_byte",
      "description": "解析 DMD 命令标志字节。",
      "description_en": "Decode a DMD command flag byte."
    },
    {
      "action_name": "auto-get_hw_status",
      "description": "get hardware status",
      "description_en": "get hardware status"
    },
    {
      "action_name": "auto-get_system_status",
      "description": "get system status",
      "description_en": "get system status"
    },
    {
      "action_name": "auto-get_main_status",
      "description": "get main status",
      "description_en": "get main status"
    },
    {
      "action_name": "auto-get_firmware_version",
      "description": "get firmware version information",
      "description_en": "get firmware version information"
    },
    {
      "action_name": "auto-get_firmware_type",
      "description": "get firmware type and tag",
      "description_en": "get firmware type and tag"
    },
    {
      "action_name": "auto-get_trigger_in1",
      "description": "get trigger input 1 settings",
      "description_en": "get trigger input 1 settings"
    },
    {
      "action_name": "auto-get_trigger_in2",
      "description": "get trigger input 2 polarity",
      "description_en": "get trigger input 2 polarity"
    },
    {
      "action_name": "auto-get_fwbatch_name",
      "description": "get firmware batch file name",
      "description_en": "get firmware batch file name"
    },
    {
      "action_name": "auto-get_dmd_sequence",
      "description": "get generated DMD pattern sequence",
      "description_en": "get generated DMD pattern sequence"
    }
  ]
}

